package net.officefloor.hq.app.period;

/** A period on a sheet: its name and its from and to dates (yyyy-MM-dd), both inclusive, whether it
 *  is closed and, once closed, its due-total fixed at that moment (two decimals). */
public record Period(String sheetId, String name, String from, String to, boolean closed,
        String closedTotal) {

    /** Whether the date (yyyy-MM-dd) falls inside it. */
    public boolean contains(String date) {
        return from.compareTo(date) <= 0 && date.compareTo(to) <= 0;
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.ClaimRepository;
import net.officefloor.hq.app.claim.Dues;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** Closes a period, fixing its due-total as it is now: the due of the claims that count whose date
 *  falls in it (n/a ones skipped, and OPEN ones dated within a hold of their person, unless bound), as the screen shows them.
 *  Refused when it is already closed. */
public class ClosePeriod {
    public void close(@PathVariable("sheetId") String sheetId, @PathVariable("name") String name,
            @RequestParam(name = "by", required = false) String by, PeriodRepository periods,
            ClaimRepository claims, PersonRepository people, RateRepository rates,
            SettingRepository settings, SheetRepository sheets,
            Out<Period> period) throws InvalidPeriodException, PeriodClosedException {
        String id = sheetId.trim();
        Period found = periods.find(id, name);
        if (found == null) {
            throw new InvalidPeriodException("No such period: " + name);
        }
        if (found.closed()) {
            throw new PeriodClosedException("The period is already closed");
        }
        String floor = settings.floor(id);
        Dues.Late late = settings.late(id, sheets.today(id));
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        for (Claim c : claims.list(id)) {
            if (!c.isCounting() || !found.contains(c.getDate())) continue;
            Person person = people.find(id, c.getPersonId());
            if (person != null && !person.countsLive(c)) continue;
            Rate rate = person == null ? null
                    : rates.find(id, person.gradeOn(c.getDate()), LocalDate.parse(c.getDate()));
            String due = Dues.shown(c, rate == null ? null : Dues.of(c.getAmount(), rate.pct(), floor, late.rounding(c.getRoundDate())), late);
            if (due != null) total = total.add(new BigDecimal(due));
        }
        period.set(periods.close(found, total, by == null ? "" : by));
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.setting.Role;
import net.officefloor.hq.app.setting.RoleRepository;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** Reopens a closed period: its due-total is live again. Refused for anyone but a steward, and when
 *  the period is not closed. */
public class ReopenPeriod {
    public void reopen(@PathVariable("sheetId") String sheetId, @PathVariable("name") String name,
            @RequestParam(name = "by", required = false) String by, PeriodRepository periods,
            RoleRepository roles, Out<Period> period) throws InvalidPeriodException, PeriodReopenException {
        String id = sheetId.trim();
        Period found = periods.find(id, name);
        if (found == null) {
            throw new InvalidPeriodException("No such period: " + name);
        }
        if (!Role.STEWARD.equals(roles.roleOf(id, by == null ? "" : by))) {
            throw new PeriodReopenException("Only a steward can reopen a period");
        }
        if (!found.closed()) {
            throw new PeriodReopenException("The period is not closed");
        }
        period.set(periods.reopen(found));
    }
}
package net.officefloor.hq.app.period;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

public class ListPeriods {
    public void list(@PathVariable("sheetId") String sheetId, PeriodRepository periods,
            ObjectResponse<List<Period>> response) {
        response.send(periods.list(sheetId.trim()));
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

@Repository
public class PeriodRepository {

    private static final RowMapper<Period> ROW = (rs, n) -> new Period(rs.getString("sheet_id"),
            rs.getString("name"), rs.getObject("from_date", LocalDate.class).toString(),
            rs.getObject("to_date", LocalDate.class).toString(), rs.getBoolean("closed"),
            rs.getBigDecimal("closed_total") == null ? null
                    : rs.getBigDecimal("closed_total").setScale(2).toPlainString());

    private static final String COLUMNS = "SELECT sheet_id, name, from_date, to_date, closed, closed_total FROM period ";

    private final JdbcTemplate jdbc;

    public PeriodRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's periods, by from-date. */
    public List<Period> list(String sheetId) {
        return jdbc.query(COLUMNS + "WHERE sheet_id = ? ORDER BY from_date", ROW, sheetId);
    }

    /** The sheet's period with the name; null when there is none. */
    public Period find(String sheetId, String name) {
        return jdbc.query(COLUMNS + "WHERE sheet_id = ? AND name = ?", ROW, sheetId, name)
                .stream().findFirst().orElse(null);
    }

    /** Refuse a change to a claim dated (yyyy-MM-dd) inside one of the sheet's closed periods. */
    public void requireOpen(String sheetId, String date) throws PeriodClosedException {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet_id = ? AND closed "
                + "AND from_date <= ? AND to_date >= ?", Integer.class, sheetId,
                LocalDate.parse(date), LocalDate.parse(date));
        if (n != null && n > 0) {
            throw new PeriodClosedException("The claim's date is inside a closed period");
        }
    }

    /** Close the period, fixing its due-total. */
    public Period close(Period period, BigDecimal total, String user) {
        jdbc.update("UPDATE period SET closed = TRUE, closed_total = ?, closed_by = ?, "
                + "closed_at = CURRENT_TIMESTAMP WHERE sheet_id = ? AND name = ?",
                total, user, period.sheetId(), period.name());
        return new Period(period.sheetId(), period.name(), period.from(), period.to(), true,
                total.toPlainString());
    }

    /** Reopen the period: its due-total is live again. */
    public Period reopen(Period period) {
        jdbc.update("UPDATE period SET closed = FALSE, closed_total = NULL, closed_by = NULL, "
                + "closed_at = NULL WHERE sheet_id = ? AND name = ?", period.sheetId(), period.name());
        return new Period(period.sheetId(), period.name(), period.from(), period.to(), false, null);
    }

    /** Whether another period on the sheet has the name, compared without regard to case. */
    public boolean nameTaken(String sheetId, String name) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet_id = ? AND name_key = LOWER(?)",
                Integer.class, sheetId, name);
        return n != null && n > 0;
    }

    /** Whether a period on the sheet shares a day with from..to (inclusive). */
    public boolean overlaps(String sheetId, LocalDate from, LocalDate to) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM period WHERE sheet_id = ? "
                + "AND from_date <= ? AND to_date >= ?", Integer.class, sheetId, to, from);
        return n != null && n > 0;
    }

    public Period add(String sheetId, String name, LocalDate from, LocalDate to, String user) {
        jdbc.update("INSERT INTO period (sheet_id, name, from_date, to_date, created_by) VALUES (?, ?, ?, ?, ?)",
                sheetId, name, from, to, user);
        return new Period(sheetId, name, from.toString(), to.toString(), false, null);
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPeriod {
    public void respond(@Val Period period, ObjectResponse<Period> response) {
        response.send(period);
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.RequestParam;

/** Last write step: only a close that went through is recorded. */
public class RecordPeriodClosed {
    public void record(@RequestParam(name = "by", required = false) String by,
            @Val Period period, Audit audit) {
        audit.record("PERIOD_CLOSED sheet=" + period.sheetId() + " by=" + (by == null ? "" : by)
                + " period=" + period.name() + " total=" + period.closedTotal());
    }
}
-- The sheet's periods: a name (unique on the sheet, compared without regard to case; stored trimmed)
-- and a from and to date, inclusive, from on or before to. No two periods on a sheet overlap (checked
-- when one is added). A claim belongs to the period whose dates contain its date, or to none.
CREATE TABLE period (
    id         BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id   VARCHAR(200) NOT NULL REFERENCES sheet (id),
    name       VARCHAR(200) NOT NULL,
    name_key   VARCHAR(200) GENERATED ALWAYS AS (LOWER(name)),
    from_date  DATE         NOT NULL,
    to_date    DATE         NOT NULL,
    created_by VARCHAR(200) NOT NULL,
    created_at TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CHECK (from_date <= to_date)
);
CREATE UNIQUE INDEX period_sheet_name ON period (sheet_id, name_key);
CREATE INDEX period_sheet_from ON period (sheet_id, from_date);
-- A closed period: its due-total is fixed at the moment it was closed (closed_total), and no claim
-- dated inside it can be added, edited, opened, settled or voided. Open until closed.
ALTER TABLE period ADD COLUMN closed BOOLEAN DEFAULT FALSE NOT NULL;
ALTER TABLE period ADD COLUMN closed_total DECIMAL(19, 2);
ALTER TABLE period ADD COLUMN closed_by VARCHAR(200);
ALTER TABLE period ADD COLUMN closed_at TIMESTAMP;
