import { useState } from 'react';
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { useSubmitOnce } from '../../forms/useSubmitOnce';
import { claimsKey, listClaims } from '../claims/api';
import { listPeople, peopleKey } from '../people/api';
import { listRates, ratesKey } from '../rates/api';
import { useFloor, useLate } from '../settings/api';
import { useSheetToday } from '../sheet/api';
import { addPeriod, closePeriod, listPeriods, periodDueTotal, periodsKey, reopenPeriod, type PeriodInput } from './api';

const EMPTY: PeriodInput = { name: '', from: '', to: '' };

/** The sheet's periods: a form that adds one, and each period by from-date with its due-total (the
 *  due of the claims that count whose date falls in it, n/a ones and OPEN unbound ones dated within their person's hold skipped; once closed, the one fixed
 *  when it was closed), whether it is closed, and buttons that close it and (a steward only) reopen it. */
export function Periods({ sheetId, user }: { sheetId: string; user: string }) {
  const queryClient = useQueryClient();
  const periods = useQuery({ queryKey: periodsKey(sheetId), queryFn: () => listPeriods(sheetId) });
  const people = useQuery({ queryKey: peopleKey(sheetId), queryFn: () => listPeople(sheetId) });
  const claims = useQuery({ queryKey: claimsKey(sheetId), queryFn: () => listClaims(sheetId) });
  const rates = useQuery({ queryKey: ratesKey(sheetId), queryFn: () => listRates(sheetId) });
  const floor = useFloor(sheetId);
  const charges = useLate(sheetId, useSheetToday(sheetId, user));
  const [form, setForm] = useState<PeriodInput>(EMPTY);

  const save = useMutation({
    mutationFn: (input: PeriodInput) => addPeriod(sheetId, user, input),
    onSuccess: () => {
      setForm(EMPTY);
      return queryClient.invalidateQueries({ queryKey: periodsKey(sheetId) });
    },
  });

  const submitOnce = useSubmitOnce();
  const actOnce = useSubmitOnce();

  // The period whose last close or reopen was refused; cleared by the next action.
  const act = useMutation({
    mutationFn: ({ name, action }: { name: string; action: 'close' | 'reopen' }) =>
      action === 'close' ? closePeriod(sheetId, user, name) : reopenPeriod(sheetId, user, name),
    onSuccess: () => queryClient.invalidateQueries({ queryKey: periodsKey(sheetId) }),
  });

  const actOne = (name: string, action: 'close' | 'reopen') => {
    actOnce(() => {
      act.reset();
      return act.mutateAsync({ name, action });
    });
  };

  const change = (patch: Partial<PeriodInput>) => {
    setForm((f) => ({ ...f, ...patch }));
    save.reset();
  };

  return (
    <section>
      <h3>Periods</h3>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          submitOnce(() => {
            save.reset();
            return save.mutateAsync(form);
          });
        }}
      >
        <label>
          Name{' '}
          <input data-testid="period-form-name" value={form.name} onChange={(e) => change({ name: e.target.value })} />
        </label>{' '}
        <label>
          From{' '}
          <input type="date" data-testid="period-form-from" value={form.from}
            onChange={(e) => change({ from: e.target.value })} />
        </label>{' '}
        <label>
          To{' '}
          <input type="date" data-testid="period-form-to" value={form.to}
            onChange={(e) => change({ to: e.target.value })} />
        </label>{' '}
        <button type="submit" data-testid="period-form-submit" disabled={save.isPending}>
          Add period
        </button>
        {save.isError && (
          <span data-testid="period-form-error">A period needs a name not already in use, and from and to dates, from on or before to, not overlapping another period.</span>
        )}
      </form>
      <table>
        <tbody>
          {(periods.data ?? []).map((p) => (
            <tr key={p.name} data-testid={`period-row-${p.name}`}>
              <td data-testid="period-name">{p.name}</td>
              <td data-testid="period-from">{p.from}</td>
              <td data-testid="period-to">{p.to}</td>
              <td>
                Due <span data-testid="period-due-total">{periodDueTotal(p, claims.data ?? [], people.data, rates.data, floor, charges)}</span>
              </td>
              <td>
                Closed <span data-testid="period-closed">{p.closed ? 'yes' : 'no'}</span>
              </td>
              <td>
                <button type="button" data-testid="period-close" disabled={act.isPending}
                  onClick={() => actOne(p.name, 'close')}>
                  Close
                </button>{' '}
                <button type="button" data-testid="period-reopen" disabled={act.isPending}
                  onClick={() => actOne(p.name, 'reopen')}>
                  Reopen
                </button>
                {act.isError && act.variables?.name === p.name && (
                  <span data-testid="period-error">{act.variables.action === 'close'
                    ? 'The period is already closed.'
                    : 'Only a steward can reopen a period, and only a closed one.'}</span>
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </section>
  );
}
import { getJson, postJson } from '../../api/http';
import { counts, liveClaims, type Claim } from '../claims/api';
import { gradeOn, type Person } from '../people/api';
import { claimDue, sumDues, type Late, type Rate } from '../rates/api';
import { sheetKey } from '../sheet/api';

/** A period on the sheet: a name (unique on the sheet) and its from and to dates (yyyy-MM-dd), both
 *  inclusive. No two periods overlap. Once closed, its due-total is the one fixed when it was closed. */
export type Period = {
  sheetId: string; name: string; from: string; to: string; closed: boolean; closedTotal: string | null;
};
export type PeriodInput = { name: string; from: string; to: string };

const base = (sheetId: string) => `/api/sheets/${encodeURIComponent(sheetId)}/periods`;

export const periodsKey = (sheetId: string) => [...sheetKey(sheetId), 'periods'] as const;

/** The sheet's periods, by from-date. */
export function listPeriods(sheetId: string): Promise<Period[]> {
  return getJson<Period[]>(base(sheetId));
}

/** Add a period; refused (rejects) when the name is missing or already in use, a date is not a date,
 *  the from-date is after the to-date, or the dates overlap another period's. */
export function addPeriod(sheetId: string, by: string, input: PeriodInput): Promise<Period> {
  return postJson<Period>(`${base(sheetId)}?by=${encodeURIComponent(by)}`, input);
}

/** The period whose dates contain the date (yyyy-MM-dd), or undefined for none. */
export function periodOf(periods: Period[] | undefined, date: string): Period | undefined {
  return (periods ?? []).find((p) => p.from <= date && date <= p.to);
}

/** Close a period, fixing its due-total; refused (rejects) when it is already closed. No claim dated
 *  inside a closed period can then be added, edited, opened, settled or voided. */
export function closePeriod(sheetId: string, by: string, name: string): Promise<Period> {
  return postJson<Period>(`${base(sheetId)}/${encodeURIComponent(name)}/close?by=${encodeURIComponent(by)}`, {});
}

/** Reopen a closed period, making its due-total live again; refused (rejects) for anyone but a
 *  steward, and when it is not closed. */
export function reopenPeriod(sheetId: string, by: string, name: string): Promise<Period> {
  return postJson<Period>(`${base(sheetId)}/${encodeURIComponent(name)}/reopen?by=${encodeURIComponent(by)}`, {});
}

/** A period's due-total as its row shows it: once closed, the one fixed when it was closed; else the
 *  due of the live claims that count whose date falls in it (n/a ones skipped). */
export function periodDueTotal(p: Period, claims: Claim[], people: Person[] | undefined, rates: Rate[] | undefined,
  floor: string, late: Late): string {
  if (p.closed && p.closedTotal !== null) return p.closedTotal;
  const personOf = new Map((people ?? []).map((q) => [q.id, q]));
  return sumDues(liveClaims(claims, people).filter(counts).filter((c) => p.from <= c.date && c.date <= p.to)
    .map((c) => claimDue(c, rates, (d) => { const q = personOf.get(c.personId); return q ? gradeOn(q, d) : ''; }, floor, late)));
}
